// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter, Initializable} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    Proxy p;

    function setUp() public {
        c = new VaultAdapter();
        p = new Proxy(address(c));
    }

    function testFuzz_property(address admin) public {
        // The adapter is constructed with _disableInitializers(), so initialize
        // must be driven through a fresh proxy whose Initializable storage slot
        // is zero; any admin address is admissible there.
        bool ok;
        bytes4 sel = VaultAdapter.initialize.selector;
        (bool success, bytes memory ret) = address(p).call(abi.encodeWithSelector(sel, admin));
        ok = success;
        // silence unused-var lint without extra assertions
        require(ret.length >= 0);
        assertTrue(ok);
    }
}

contract Proxy {
    bytes32 private constant _IMPL_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    constructor(address impl) {
        assembly {
            sstore(_IMPL_SLOT, impl)
        }
    }

    fallback() external payable {
        assembly {
            let ptr := mload(0x40)
            calldatacopy(ptr, 0, calldatasize())
            let r := delegatecall(gas(), sload(_IMPL_SLOT), ptr, calldatasize(), 0, 0)
            returndatacopy(ptr, 0, returndatasize())
            switch r
            case 0 {
                revert(ptr, returndatasize())
            }
            default {
                return(ptr, returndatasize())
            }
        }
    }
}
